WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (505::BIGINT, 'Es un buen profe. Explica bien la materia y hace algunos ejercicios. Se le entiende bien, y si no entiendes algo puedes preguntarle con confianza. Las horas de consulta también son buenas. Sí manda tareas, pero nada del otro mundo, dos quices fáciles.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, '316167a65a806e4d198955a4083d392421751b74ee9ce6ddeabeefe6eb5df3a1'::TEXT, ARRAY[634]::BIGINT[]),
    (505::BIGINT, 'Es un señor a la antigua, todo lo hace en la pizarra. Es muy amable y simpático, sus explicaciones a veces son confusas (hay maneras más fácil de explicar). Deja bastantes tareas y quices. Califica ok, justamente. Si tiene opción matricule con otro, y si no tiene opción no es del todo malo (se pasa)'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '844eb518b015f67e262aa6ba7c696222fee1cf7ef4ff80a3a0a70823538bb672'::TEXT, ARRAY[605]::BIGINT[]),
    (505::BIGINT, 'es un aburrimiento el señor xd no se le entiende nada y copia todo en la pizarra pero es fácil pasar nada mas no se salte prosedimiento vease las clases de reiman y con eso pasa bien'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, '12c26a63401020abe4a608ce86ac1cf2f57e356074cf2bdfe115a9770b9dfaae'::TEXT, ARRAY[634]::BIGINT[]),
    (505::BIGINT, 'El profe es muy chill, las clases son un toque aburridas y todo los escribe en la pizarra (en veces no se entiende mucho la letra) pero en general explica bien Califica medio suave, las tareas no son largas y hace como 4 quices que están ok'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'd5f041a84d6a159d6ff8ddd925f004654b6c039aaeac9c075b44bdd311bccb65'::TEXT, ARRAY[634]::BIGINT[]),
    (505::BIGINT, 'La clase es muy relajada con él y explica bien los ejercicios, las tareas no son difíciles, pero los quizzes sí son más difíciles que los exámenes porque pone integrales difíciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '249afe3bc4fe9dbb3867c40a2732ab81e4f1a29d099ecd5754c7d0bc4cd3b316'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'El profesor es bastante mediocre, califica duro, se confunde con lo que hace y escribe confuso en la pizarra'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2025-12-01T00:00:00+00:00'::TIMESTAMPTZ, '415fe366388adec59f9cbbc75bf298ee3c0462bc25a88639488e29e0907fc639'::TEXT, ARRAY[634]::BIGINT[]),
    (505::BIGINT, 'Los quices son muy largos y complicados aunque el asistente revisa normal. Los exámenes los califica a matar, no da puntos ni por procedimiento. En clases es un desorden escribiendo en la pizzara y no usa presentaciones como apoyo entonces no hay material como para ver procedimientos y ejemplos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2025-10-01T00:00:00+00:00'::TIMESTAMPTZ, '470b362527d23a5cd033061caf7408062cdad5cc86b1221cc14332386c595e65'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Buen profe y muy buena gente. Sus explicaciones van al grano y trata de explicar lo que es útil en la práctica. Califica suave. Yo lo tuve semipresencial y fueron solo 8 clases presencial y la demás virtuale, el dejaba las grabaciones para repasar. Buena opción en general.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, '6f88bece628659d221c4130c721f9b70cc4e5b728236fc27287ec305781dcc91'::TEXT, ARRAY[923]::BIGINT[]),
    (505::BIGINT, 'El profe sabe mucho, pero es un señor, o sea el enseña al estilo de la vieja escuela, revuelve temas, y no llega a algo claro, se equivoca aveces resolviendo ejercicios, asi que lo mejor es estudiar con los videos de Alexander Borbon, califica justo, no es tan rudo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, '837c20ee6920c81604eca759943a4633a3d7eccf80d54e37e59c95e01ef57bb5'::TEXT, ARRAY[923]::BIGINT[]),
    (505::BIGINT, 'Se equivoca resolviendo los ejercicios, pero normalmente se da cuenta, sabe demasiado, desprende tranquilidad. El curso no es tan pesado entonces con buena práctica se pasa. Matricule sin miedo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'b2ce58843ef53974bb5f4b58a292b8d08b161d1d5688761f2f77e14a47d29c22'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Tenía como 10 años de no dar el curso. Es buena gente, califica suave, deja muchas tareas y pocos quices. El único problema es que en clase solo hace dos ejemplos (que toman las dos horas de clase) y que aveces deja temas por fuera que entran en el examen.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3b02b5775a8467923f3ecc7831859f41997880847cf767f64fbee205c6c0e6e8'::TEXT, ARRAY[923]::BIGINT[]),
    (505::BIGINT, 'No explica bien, siempre esta perdido con la cátedra y mezcla muchos temas. Los quizes no son tan complicados. Es pasable pero de fijo va a necesitar explicaciones de otro profe o de otro material.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd05143769cf5403360b7b0c79f13569caf4320da70fc025aef37254a38a9b5d5'::TEXT, ARRAY[923]::BIGINT[]),
    (505::BIGINT, 'Muy buen profe, es sumamente comprensivo. La materia a pesar de ser mucha da lo necesario. Los quices un poco difíciles pero la mayoría son virtuales.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'ebdd61d6ca5e456a0f5f306b2379fb11e5d02c740719e83df6d642b14d65bc0d'::TEXT, ARRAY[103]::BIGINT[]),
    (505::BIGINT, 'Creo que explica bien pero en ocasiones se confunde y es un poco desordenado. En general el curso no es difícil, el profe cumple bien con su labor y califica de manera justa. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'efcfd6ca89a445fbc4e6a87b3ce4de48a83e10a693a9a8105699a5cf83ff4275'::TEXT, ARRAY[103]::BIGINT[]),
    (505::BIGINT, 'Los contenidos del curso no son complicados, él es el que los complica al llegar a leer el libro del otro profesor sumado con que pasa enredándose mientras explica.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-26T00:00:00+00:00'::TIMESTAMPTZ, '57cacb0c9a7f72f359b5d6563ef90fa95480df50607ba4927a5a9821dd71386c'::TEXT, ARRAY[103]::BIGINT[]),
    (505::BIGINT, 'Con el es fácil pasar solo si usted le pone a estudiar exámenes viejos del curso e ir a tutoría que sirve bastante porque el no profundiza algunos puntos importantes para los exámenes. sus quices son fáciles en comparación con otros profes. lo recomiendo pero es mejor con Alexander Borbon'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '039c9d6334236df94732f4f330339ff10018a50e70489bb8ba567160da3e3856'::TEXT, ARRAY[634]::BIGINT[]),
    (505::BIGINT, 'Explica bien pero no hace toda la práctica que uno quisiera. Califica duro las tareas, quices y no da casi puntos por procedimiento. Califica mejor los exámenes catédrados.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e1b8ee1b22863c08c2c21386d84cabc0297811be7110864ecae9c86da0ef9baf'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'siempre esta detras del palo con todo respeto a la catedra , hay que tener cuidado y revisar bien cuando te devuelve el examen por que se equivoca mucho, es bastante flexible con las clases'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-22T00:00:00+00:00'::TIMESTAMPTZ, '84344adf41bcf7513e45c3f3b1c11c69bf2ad22ae6b887236862be059a0371db'::TEXT, ARRAY[634]::BIGINT[]),
    (505::BIGINT, 'Es un muy buen profe, explica las cosas con mucha calma y apoya mucho al estudiante con sus dudas. Lo único es que aveces se pierde tiempo en clase por ir tan lento y se resuelven en las dos horas dos ejercicios. Si busca un profe que haga mucha práctica no es el mejor pero es uno que explica exc!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'b42e03c663008a1a0f8f0ab717b76f5aa8b93413f6a8b9dc71c20ab50cf053ac'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Explica bien, hay que practicar bastante, les recomiendo llevar la materia al dia y ver videos de Matefacil para complementar. Los quices presenciales que hace son faciles, evalua bastante el procedimiento. Los quices en el GAAP son con bastante tiempo para hacerlos...'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '0f7af329c7a94462e018d16806118d77b287aba59efd1975c1a7a9b20636d899'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'El profe es bueno, no es increible. Las tareas y quizes son faciles y las clases ayudan pero dejan algunos vacios que hay que tener en cuenta para examenes. Es bastante accesible y ayuda a los estudiantes que lo solicitan.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '8add2515bb8c848308e80d114042af7887d715bc9e953ab3105bd17502c9884e'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Realmente explica muy bien, incluso me encuentro volviendo a ver las clases grabadas al no entender viendo los temas con algún canal de youtube de los buenos para ED como matefácil, porque el profe deja muy clara la materia, de verdad muy recomendado..'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'f744a4a9230e311539ba66dbbfd6ad107520596ba96ec159f81048e8cd590b4c'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'profe bueno, pero no excelente Buena opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '1b1fe0832d4c9692e41b097a1a0d43de727d9d6642e4583349215e3673174dbd'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Aprovecha las dos horas de clase y explica bastante, el curso en si es dificil pero el lo hace entendi, si uno saca el rato para las clases, esta atento y practica lo justo pasa bien'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, '687e9fa195463d9daf9ffe58c6f18010adb11f0f617de0e0299c466521b15954'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Es un buen profe, no le tenga miedo. El curso en si es rudo pero el mae lo hace ameno, aún así tiene que sacar su tiempo, no es un regalo. Si usted ve las clases y saca unos dos días antes del examen para practicar pasa sin broncas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1739e6111564f4cbf60f2e1fb19ce01c686cfd413d147db315b992a2ae9bf26c'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Excelente profesor. Lleve ecuaciones con él en verano. Se le entiende todo. Además es muy buena gente. Solo hicimos exámenes, nada de tareas o quices.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2020-08-29T00:00:00+00:00'::TIMESTAMPTZ, '3c0d044b11395d51b479c5ad7c3a7d2936d05840ae41de3009ac1c77f99ae4ef'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Hay que agarrarle el toque al inicio pero es de enseñar con ejemplos y ejercicios de práctica en clase y se entiende fácil si se pone atención'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2020-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'c9f7c9eb22e23ef5e07c02a0fe5dd6302e7379005dcd735882479558eaf6875a'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'be989156965c810e3e87f9771ba93f6f42c5febcd0bf76e34bb53d671a1b11ac'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'b9c2ebf82f05fca34ff965963e2063fb635963580a1b31fbcc4f6937f4fbc847'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '2b2863f63e44599309ea538b2ab432a7327a9f905c0358b74ad525683d30f114'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Muy buen profe, se le entiende bastante bien. Lo recomiendo mucho para verano'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0b278e2c5a77d330f46e70b76c2a60fc19bb91ec4a16e6cd06e199c8aec5e1ae'::TEXT, ARRAY[923]::BIGINT[]),
    (505::BIGINT, 'Explicando la materia, se enreda en ocasiones. Repite la explicación si se lo piden. Deja tareas todas las semanas y tienen un nivel de dificultad tipo examen. En consulta, no resuelve ejercicios; lo que hace es dar una guía de cómo puede resolverse. Recomendado para repitentes del curso.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '74a6ecd6ed9e22024add93fb18f89db19ac18fbdc907fe5e1f8244b27915bf36'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Excelente profe, recomendado para verano. Las clases son muy compresibles y el curso se pasa relax.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '97f071951b2bb49de3e7133290e25ee314a20842fa03a5c7fc6e166140a07ce9'::TEXT, ARRAY[923]::BIGINT[]),
