    (505::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '32b35b4efade967e6a640bcb8232db8d8605877de5dc9644fe8a47a88e994b98'::TEXT, ARRAY[935]::BIGINT[]),
    (505::BIGINT, 'Excelente profesor, no haced quices, solo deja tarras para la casa y eso ayuds mucho, ademas de explicar SUPER bien, califica suave a mi parecer, nada mas que pedirle a la vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '0efb22c445a786bc76f8641af275233ac2a94c63770f4f2863ba42c694472547'::TEXT, ARRAY[935]::BIGINT[]),
